function startBannerAuto(){
  const banner=__id("homeBanner");if(!banner)return;
  if(!banner.dataset.bound){
    banner.dataset.bound="1";
    let paused=false;
    banner.addEventListener("pointerdown",()=>{paused=true});
    banner.addEventListener("pointerup",()=>{setTimeout(()=>{paused=false},4000)});
    banner.addEventListener("scroll",()=>{
      const cards=banner.querySelectorAll(".hb-card");if(!cards.length)return;
      let best=0,bd=1e9;
      cards.forEach((c,i)=>{const d=Math.abs(c.offsetLeft-banner.scrollLeft);if(d<bd){bd=d;best=i}});
      homeBannerIdx=best;
      __all(".hb-dot").forEach((d,i)=>d.classList.toggle("active",i===best));
    },{passive:true});
  }
  clearInterval(homeBannerTimer);
  homeBannerTimer=setInterval(()=>{
    if(document.hidden)return;
    const cards=banner.querySelectorAll(".hb-card");if(cards.length<2)return;
    homeBannerIdx=(homeBannerIdx+1)%cards.length;
    banner.scrollTo({left:cards[homeBannerIdx].offsetLeft,behavior:"smooth"});
  },4500);
}
