function handleEpisodeEnd(){
  const mode=playerSettings.playMode;const eps=playerSources[playerSrc]||[];if(!eps.length)return;
  if(mode==="repeat-one"){try{videoEl.currentTime=0;videoEl.play().catch(()=>{});}catch(e){}toast("\u5355\u96C6\u5FAA\u73AF");return;}
  if(mode==="random"){let next=Math.floor(Math.random()*eps.length);if(eps.length>1&&next===playerEp)next=(next+1)%eps.length;playEp(next);toast("\u968F\u673A\u64AD\u653E");return;}
  if(playerEp<eps.length-1){playEp(playerEp+1);return;}
  if(mode==="loop"){playEp(0);toast("\u5217\u8868\u5FAA\u73AF\uFF0C\u56DE\u5230\u7B2C\u4E00\u96C6");return;}
  toast("\u5DF2\u64AD\u5B8C\u6700\u540E\u4E00\u96C6");
}
