function wtIdenticon(seed){
  const key=String(seed||"anon");
  if(wtIdentCache[key])return wtIdentCache[key];
  let h=2166136261>>>0;
  for(let i=0;i<key.length;i++){h=((h^key.charCodeAt(i))>>>0);h=Math.imul(h,16777619)>>>0;}
  const hue=h%360,bg="hsl("+hue+" 55% 92%)",fg="hsl("+hue+" 55% 42%)";
  let cells="";
  for(let y=0;y<5;y++)for(let x=0;x<3;x++){
    if(((h>>((y*3+x)%30))&1)===0)continue;
    cells+='<rect x="'+x+'" y="'+y+'" width="1" height="1"/><rect x="'+(4-x)+'" y="'+y+'" width="1" height="1"/>';
  }
  const svg='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 5 5" shape-rendering="crispEdges"><rect width="5" height="5" fill="'+bg+'"/><g fill="'+fg+'">'+cells+"</g></svg>";
  const url="data:image/svg+xml,"+encodeURIComponent(svg);
  wtIdentCache[key]=url;return url;
}
